package br.com.cineo;
import android.view.*;import android.widget.*;import android.os.SystemClock;import org.json.*;import java.util.*;
/** Read navigation is independent of uploads/writes. Cached callbacks run once, never append twice. */
class ReadFlow {
 final MainActivity a;final Object authLock=new Object();int pending=0;long hits=0,requests=0;final ArrayList<Long> times=new ArrayList<>();
 ReadFlow(MainActivity activity){a=activity;}
 void ensureSession(String account)throws Exception{synchronized(authLock){if(!account.equals(a.uid))throw new java.io.IOException("Conta alterada.");if(!a.refresh.isEmpty()&&System.currentTimeMillis()/1000>a.expires-60){JSONObject r;try{r=a.request("POST","/refresh",a.obj("refresh_token",a.refresh),"");}catch(MainActivity.ApiError invalid){if(invalid.code==400||invalid.code==401)throw new MainActivity.ApiError(401,"Sessão expirada.");throw invalid;}if(!account.equals(a.uid))throw new java.io.IOException("Conta alterada.");a.session(r);}}}
 void error(Exception error){if(error instanceof MainActivity.ApiError){int code=((MainActivity.ApiError)error).code;if(code==423){a.viewerToken="";a.fastCache.invalidate();a.accounts.profiles();return;}if(code==401){a.fastCache.invalidate();a.clearSession();a.login(false);a.notice("Sua sessão expirou. Entre novamente.",true);return;}}a.notice(error instanceof java.io.IOException?"Não foi possível atualizar agora. Confira sua conexão.":error.getMessage(),true);}
 void get(String path,MainActivity.Done done){get(path,done,false);}
 void get(String path,MainActivity.Done done,boolean refreshView){if(a.errorRetry!=null){if(a.errorRetry.getParent() instanceof ViewGroup)((ViewGroup)a.errorRetry.getParent()).removeView(a.errorRetry);a.errorRetry=null;}final int page=a.generation;final String account=a.uid,viewer=a.viewerToken,scope=a.fastCache.scope();final long epoch=a.fastCache.epoch;boolean forced=a.fastCache.force;a.fastCache.force=false;FastCache.Entry cached=a.fastCache.get(scope,path);final boolean delivered=cached!=null;
  if(cached!=null){hits++;a.safe(()->done.run(cached.value()));if(page!=a.generation)return;if(!forced&&System.currentTimeMillis()-cached.at<FastCache.FRESH)return;}
  pending++;if(!delivered){a.loading.setVisibility(View.VISIBLE);a.notice("Buscando informações…",false);}final long start=SystemClock.elapsedRealtime();a.reads.execute(()->{try{if(page!=a.generation)return;a.requestGeneration.set(page);a.requestViewer.set(viewer);ensureSession(account);if(page!=a.generation||!viewer.equals(a.viewerToken))return;JSONObject response=a.request("GET",path,null,a.token);if(!account.equals(a.uid)||!viewer.equals(a.viewerToken))return;a.fastCache.put(scope,path,response,epoch);record(SystemClock.elapsedRealtime()-start);a.runOnUiThread(()->{if(page!=a.generation||!account.equals(a.uid)||!viewer.equals(a.viewerToken))return;pending=Math.max(0,pending-1);if(pending==0&&!a.busy){a.loading.setVisibility(View.GONE);a.notice("",false);}if(!delivered||refreshView){if(refreshView&&delivered){ScrollView scroll=(ScrollView)a.body.getParent();int y=scroll.getScrollY();a.safe(()->done.run(response));scroll.post(()->scroll.scrollTo(0,y));}else a.safe(()->done.run(response));}});}catch(Exception error){a.runOnUiThread(()->{if(page!=a.generation)return;pending=Math.max(0,pending-1);if(pending==0&&!a.busy)a.loading.setVisibility(View.GONE);if(delivered&&!(error instanceof MainActivity.ApiError)){a.notice("Conteúdo salvo neste aparelho. Você pode tentar atualizar depois.",false);return;}error(error);if(a.generation==page){a.errorRetry=a.button(a.body,"Tentar novamente",MainActivity.CARD,()->{a.fastCache.force=true;get(path,done,refreshView);});}});}finally{a.requestGeneration.remove();a.requestViewer.remove();}});
 }
 synchronized void record(long ms){requests++;times.add(ms);if(times.size()>100)times.remove(0);}
 synchronized long median(){if(times.isEmpty())return 0;ArrayList<Long> sorted=new ArrayList<>(times);Collections.sort(sorted);return sorted.get(sorted.size()/2);}
 void metrics(){a.page("performance","Velocidade do aplicativo","Informações deste aparelho.",3,()->a.dashboard.preferences());a.title(a.body,hits+" leituras atendidas pelo conteúdo salvo",21);a.text(a.body,requests+" consultas concluídas\nTempo mediano das consultas: "+median()+" ms\nTelas guardadas em memória: "+a.fastCache.count(),14,MainActivity.MUTED);a.text(a.body,"Os números são medidos no seu aparelho e dependem da conexão. Nenhuma senha ou conteúdo de mensagens é registrado nesta medição.",13,MainActivity.MUTED);a.button(a.body,"Limpar conteúdo temporário",MainActivity.CARD,()->{a.fastCache.invalidate();a.notice("Conteúdo temporário removido. Conta e publicações foram preservadas.",false);});}
}
